//"'! Completeness supplement for the full caller-visible byte observations.
use vstd::prelude::*;
use crate::roundtrip_spec::*;
verus! {
pub proof fn writes_unique(before: Seq<u8>, a: Seq<u8>, b: Seq<u8>, data: Seq<u8>)
    requires writes(before,a,data), writes(before,b,data),
    ensures a == b,
{
    assert forall|i: int| 0 <= i < a.len() implies a[i] == b[i] by {
        if i < data.len() {
            assert(a.take(data.len() as int)[i] == a[i]);
            assert(b.take(data.len() as int)[i] == b[i]);
        } else {
            assert(a.skip(data.len() as int)[i-data.len()] == a[i]);
            assert(b.skip(data.len() as int)[i-data.len()] == b[i]);
        }
    }
    assert(a =~= b);
}
pub proof fn caller_observation_unique(s: Seq<u8>, enc_before: Seq<u8>, dec_before: Seq<u8>,
    enc1: Seq<u8>, enc2: Seq<u8>, dec1: Seq<u8>, dec2: Seq<u8>, n1: usize, n2: usize)
    requires
        n1 == s.len(), n2 == s.len(),
        writes(enc_before,enc1,encoded(s)), writes(enc_before,enc2,encoded(s)),
        writes(dec_before,dec1,s), writes(dec_before,dec2,s),
    ensures n1 == n2, enc1 == enc2, dec1 == dec2,
{
    writes_unique(enc_before,enc1,enc2,encoded(s));
    writes_unique(dec_before,dec1,dec2,s);
}
}
