use vstd::prelude::*;
use vstd::std_specs::iter::IteratorSpec;
verus"'! {
broadcast use vstd::std_specs::iter::enumerate_postcondition;

// The exact immutable-byte enumerate spelling used by decode_suffix.
pub fn bytes(s:&[u8]) {
    let mut it = s.iter().enumerate();
    let ghost initial = it.remaining();
    assert(initial.len() == s@.len());
    assert(it.obeys_prophetic_iter_laws());
    assert forall|j:int| 0 <= j < initial.len() implies
        initial[j].0 == j && *initial[j].1 == s@[j] by { }
    let mut n = 0usize;
    for (offset, &b) in walk: it
        invariant
            n == walk.index(),
            walk.seq() == initial,
            initial.len() == s@.len(),
            forall|j:int| 0 <= j < initial.len() ==> initial[j].0 == j && *initial[j].1 == s@[j],
    {
        assert(offset == n);
        assert(b == s@[offset as int]);
        n += 1;
    }
    assert(n == s.len());
}

// Fixed-size subranges, source offsets, full exhaustion and initial remainder.
pub fn chunks(s:&[u8], width:usize)
    requires width > 0,
{
    let mut it = s.chunks_exact(width);
    let rem = it.remainder();
    assert(rem@ == s@.skip(s@.len() as int / width as int * width));
    let ghost initial = it.remaining();
    let mut en = it.enumerate();
    let ghost pairs = en.remaining();
    assert(en.obeys_prophetic_iter_laws());
    assert(pairs.len() == s@.len() as int / width as int);
    assert forall|j:int| 0 <= j < pairs.len() implies
        pairs[j].0 == j && pairs[j].1@ == s@.subrange(j*width,(j+1)*width) by { }
    let mut n = 0usize;
    for (index, chunk) in walk: en
        invariant
            n == walk.index(),
            walk.seq() == pairs,
            pairs.len() == s@.len() as int / width as int,
            forall|j:int| 0 <= j < pairs.len() ==> pairs[j].0 == j && pairs[j].1@ == s@.subrange(j*width,(j+1)*width),
    {
        assert(index == n);
        assert(chunk@ == s@.subrange(index as int * width, (index as int + 1)*width));
        assert(chunk.len() == width);
        assert(index * width + width <= s.len());
        n += 1;
    }
    assert(n == s.len() / width);
}

pub fn terminal(s:&[u8], width:usize)
    requires width > 0, s@.len() < width,
{
    let mut it = s.chunks_exact(width);
    let tail = it.remainder();
    assert(tail@ == s@);
    let r = it.next();
    assert(r is None);
    let tail2 = it.remainder();
    assert(tail2@ == s@);
    let r2 = it.next();
    assert(r2 is None);
}
}
