    assert(b.unwrap()@ == s@.subrange(2,4));
    let r2=it.remainder();
    assert(r2@ == r0@);
    let c=it.next();
    assert(c is None);
    let d=it.next();
    assert(d is None);
    let r3=it.remainder();
    assert(r3@ == r0@);
}
